-- Katalog resmi ICF (WHO): 1424 kode level 2-4, 30 bab, skala kualifier.
-- Sumber: ICF_Template.xlsx (konversi PDF ICF WHO, bahasa Inggris). Dipakai Assessment otomatis.
create table if not exists public.icf_chapters (
  chapter_code text primary key, component text not null, component_code text not null,
  chapter_no int not null, chapter_title text not null, description text
);
create table if not exists public.icf_codes (
  code text primary key, title text not null, level int not null, parent_code text,
  component_code text not null, chapter_code text references public.icf_chapters(chapter_code),
  definition text, residual boolean not null default false, seq int not null
);
create index if not exists icf_codes_parent_idx on public.icf_codes(parent_code);
create table if not exists public.icf_qualifiers (
  component_code text not null, qualifier_no int not null, qualifier_name text not null,
  value text not null, label text not null, synonyms text, percent_range text,
  primary key (component_code, qualifier_no, value)
);
alter table public.icf_chapters enable row level security;
alter table public.icf_codes enable row level security;
alter table public.icf_qualifiers enable row level security;
create policy "icf_chapters_read" on public.icf_chapters for select to authenticated using (true);
create policy "icf_codes_read" on public.icf_codes for select to authenticated using (true);
create policy "icf_qualifiers_read" on public.icf_qualifiers for select to authenticated using (true);
on conflict (chapter_code) do nothing;
on conflict do nothing;

on conflict (code) do nothing;

on conflict (code) do nothing;

on conflict (code) do nothing;

on conflict (code) do nothing;
