insert into public.icf_chapters(component,component_code,chapter_code,chapter_no,chapter_title,description) values
('Body Functions','b','b1',1,'Mental functions','This chapter is about the functions of the brain: both global mental functions, such as consciousness, energy and drive, and specific mental functions, such as memory, language and calculation mental functions.'),
('Body Functions','b','b2',2,'Sensory functions and pain','This chapter is about the functions of the senses, seeing, hearing, tasting and so on, as well as the sensation of pain.'),
('Body Functions','b','b3',3,'Voice and speech functions','This chapter is about the functions of producing sounds and speech.'),
('Body Functions','b','b4',4,'Functions of the cardiovascular, haematological, immunological and respiratory systems','This chapter is about the functions involved in the cardiovascular system (functions of the heart and blood vessels), the haematological and immunological systems (functions of blood production and immunity), and the respiratory system (functions of respiration and exercise tolerance).'),
('Body Functions','b','b5',5,'Functions of the digestive, metabolic and endocrine systems','This chapter is about the functions of ingestion, digestion and elimination, as well as functions involved in metabolism and the endocrine glands.'),
('Body Functions','b','b6',6,'Genitourinary and reproductive functions','This chapter is about the functions of urination and the reproductive functions, including sexual and procreative functions.'),
('Body Functions','b','b7',7,'Neuromusculoskeletal and movement-related functions',null),
('Body Functions','b','b8',8,'Functions of the skin and related structures','This chapter is about the functions of skin, nails and hair.'),
('Body Structures','s','s1',1,'Structures of the nervous system',null),
('Body Structures','s','s2',2,'The eye, ear and related structures',null),
('Body Structures','s','s3',3,'Structures involved in voice and speech',null),
('Body Structures','s','s4',4,'Structures of the cardiovascular, immunological and respiratory systems',null),
('Body Structures','s','s5',5,'Structures related to the digestive, metabolic and endocrine systems',null),
('Body Structures','s','s6',6,'Structures related to the genitourinary and reproductive systems',null),
('Body Structures','s','s7',7,'Structures related to movement',null),
('Body Structures','s','s8',8,'Skin and related structures',null),
('Activities and Participation','d','d1',1,'Learning and applying knowledge','This chapter is about learning, applying the knowledge that is learned, thinking, solving problems, and making decisions.'),
('Activities and Participation','d','d2',2,'General tasks and demands','This chapter is about general aspects of carrying out single or multiple tasks, organizing routines and handling stress. These items can be used in conjunction with more specific tasks or actions to identify the underlying features of the execution of tasks under different circumstances.'),
('Activities and Participation','d','d3',3,'Communication','This chapter is about general and specific features of communicating by language, signs and symbols, including receiving and producing messages, carrying on conversations, and using communication devices and techniques.'),
('Activities and Participation','d','d4',4,'Mobility','This chapter is about moving by changing body position or location or by transferring from one place to another, by carrying, moving or manipulating objects, by walking, running or climbing, and by using various forms of transportation.'),
('Activities and Participation','d','d5',5,'Self-care','This chapter is about caring for oneself, washing and drying oneself, caring for one''s body and body parts, dressing, eating and drinking, and looking after one’s health.'),
('Activities and Participation','d','d6',6,'Domestic life','This chapter is about carrying out domestic and everyday actions and tasks. Areas of domestic life include acquiring a place to live, food, clothing and other necessities, household cleaning and repairing, caring for personal and other household objects, and assisting others.'),
('Activities and Participation','d','d7',7,'Interpersonal interactions and relationships','This chapter is about carrying out the actions and tasks required for basic and complex interactions with people (strangers, friends, relatives, family members and lovers) in a contextually and socially appropriate manner.'),
('Activities and Participation','d','d8',8,'Major life areas','This chapter is about carrying out the tasks and actions required to engage in education, work and employment and to conduct economic transactions.'),
('Activities and Participation','d','d9',9,'Community, social and civic life','This chapter is about the actions and tasks required to engage in organized social life outside the family, in community, social and civic areas of life.'),
('Environmental Factors','e','e1',1,'Products and technology','This chapter is about the natural or human-made products or systems of products, equipment and technology in an individual''s immediate environment that are gathered, created, produced or manufactured. The ISO 9999 classification of technical aids defines these as "any product, instrument, equipment or technical system used by a disabled person, especially produced or generally available, preventing, compensating, monitoring, relieving or neutralizing" disability. It is recognized that any product or technology can be assistive. (See ISO 9999: Technical aids for disabled persons - Classification (second version); ISO/TC 173/SC 2; ISO/DIS 9999 (rev.).) For the purposes of this classification of environmental factors, however, assistive products and technology are defined more narrowly as any product, instrument, equipment or technology adapted or specially designed for improving the functioning of a disabled person.'),
('Environmental Factors','e','e2',2,'Natural environment and human-made changes to environment','This chapter is about animate and inanimate elements of the natural or physical environment, and components of that environment that have been modified by people, as well as characteristics of human populations within that environment.'),
('Environmental Factors','e','e3',3,'Support and relationships','This chapter is about people or animals that provide practical physical or emotional support, nurturing, protection, assistance and relationships to other persons, in their home, place of work, school or at play or in other aspects of their daily activities. The chapter does not encompass the attitudes of the person or people that are providing the support. The environmental factor being described is not the person or animal, but the amount of physical and emotional support the person or animal provides.'),
('Environmental Factors','e','e4',4,'Attitudes','This chapter is about the attitudes that are the observable consequences of customs, practices, ideologies, values, norms, factual beliefs and religious beliefs. These attitudes influence individual behaviour and social life at all levels, from interpersonal relationships and community associations to political, economic and legal structures; for example, individual or societal attitudes about a person''s trustworthiness and value as a human being may motivate positive, honorific practices or negative and discriminatory practices (e.g. stigmatizing, stereotyping and marginalizing or neglect of the person). The attitudes classified are those of people external to the person whose situation is being described. They are not those of the person themselves. The individual attitudes are categorized according to the kinds of relationships listed in Environmental Factors Chapter 3. Values and beliefs are not coded separately from attitudes as they are assumed to be the driving forces behind the attitudes.'),
('Environmental Factors','e','e5',5,'Services, systems and policies','This chapter is about: 1. Services that provide benefits, structured programmes and operations, in various sectors of society, designed to meet the needs of individuals. (Included in services are the people who provide them.) Services may be public, private or voluntary, and may be established at a local, community, regional, state, provincial, national or international level by individuals, associations, organizations, agencies or governments. The goods provided by these services may be general or adapted and specially designed. 2. Systems that are administrative control and organizational mechanisms, and are established by governments at the local, regional, national, and international levels, or by other recognized authorities. These systems are designed to organize, control and monitor services that provide benefits, structured programmes and operations in various sectors of society. 3. Policies constituted by rules, regulations, conventions and standards established by governments at the local, regional, national, and international levels, or by other recognized authorities. Policies govern and regulate the systems that organize, control and monitor services, structured programmes and operations in various sectors of society.')
