insert into public.icf_codes(seq,code,title,level,parent_code,component_code,chapter_code,definition,residual) values
(1,'b110','Consciousness functions',2,'b1','b','b1','General mental functions of the state of awareness and alertness, including the clarity and continuity of the wakeful state.',false),
(2,'b1100','State of consciousness',3,'b110','b','b1','Mental functions that when altered produce states such as clouding of consciousness, stupor or coma.',false),
(3,'b1101','Continuity of consciousness',3,'b110','b','b1','Mental functions that produce sustained wakefulness, alertness and awareness and, when disrupted, may produce fugue, trance or other similar states.',false),
(4,'b1102','Quality of consciousness',3,'b110','b','b1','Mental functions that when altered effect changes in the character of wakeful, alert and aware sentience, such as drug-induced altered states or delirium.',false),
(5,'b1108','Consciousness functions, other specified',3,'b110','b','b1',null,true),
(6,'b1109','Consciousness functions, unspecified',3,'b110','b','b1',null,true),
(7,'b114','Orientation functions',2,'b1','b','b1','General mental functions of knowing and ascertaining one’s relation to self, to others, to time and to one’s surroundings.',false),
(8,'b1140','Orientation to time',3,'b114','b','b1','Mental functions that produce awareness of day, date, month and year.',false),
(9,'b1141','Orientation to place',3,'b114','b','b1','Mental functions that produce awareness of one''s location, such as one''s immediate surroundings, one''s town or country.',false),
(10,'b1142','Orientation to person',3,'b114','b','b1','Mental functions that produce awareness of one''s own identity and of individuals in the immediate environment.',false),
(11,'b11420','Orientation to self',4,'b1142','b','b1','Mental functions that produce awareness of one''s own identity.',false),
(12,'b11421','Orientation to others',4,'b1142','b','b1','Mental functions that produce awareness of the identity of other individuals in one''s immediate environment .',false),
(13,'b11428','Orientation to person, other specified',4,'b1142','b','b1',null,true),
(14,'b11429','Orientation to person, unspecified',4,'b1142','b','b1',null,true),
(15,'b1148','Orientation functions, other specified',3,'b114','b','b1',null,true),
(16,'b1149','Orientation functions, unspecified',3,'b114','b','b1',null,true),
(17,'b117','Intellectual functions',2,'b1','b','b1','General mental functions, required to understand and constructively integrate the various mental functions, including all cognitive functions and their development over the life span.',false),
(18,'b122','Global psychosocial functions',2,'b1','b','b1','General mental functions, as they develop over the life span, required to understand and constructively integrate the mental functions that lead to the formation of the interpersonal skills needed to establish reciprocal social interactions, in terms of both meaning and purpose.',false),
(19,'b126','Temperament and personality functions',2,'b1','b','b1','General mental functions of constitutional disposition of the individual to react in a particular way to situations, including the set of mental characteristics that makes the individual distinct from others.',false),
(20,'b1260','Extraversion',3,'b126','b','b1','Mental functions that produce a personal disposition that is outgoing, sociable and demonstrative, as contrasted to being shy, restricted and inhibited.',false),
(21,'b1261','Agreeableness',3,'b126','b','b1','Mental functions that produce a personal disposition that is cooperative, amicable, and accommodating, as contrasted to being unfriendly, oppositional and defiant.',false),
(22,'b1262','Conscientiousness',3,'b126','b','b1','Mental functions that produce personal dispositions such as in being hard-working, methodical and scrupulous, as contrasted to mental functions producing dispositions such as in being lazy, unreliable and irresponsible.',false),
(23,'b1263','Psychic stability',3,'b126','b','b1','Mental functions that produce a personal disposition that is even-tempered, calm and composed, as contrasted to being irritable, worried, erratic and moody.',false),
(24,'b1264','Openness to experience',3,'b126','b','b1','Mental functions that produce a personal disposition that is curious, imaginative, inquisitive and experience-seeking, as contrasted to being stagnant, inattentive and emotionally inexpressive.',false),
(25,'b1265','Optimism',3,'b126','b','b1','Mental functions that produce a personal disposition that is cheerful, buoyant and hopeful, as contrasted to being downhearted, gloomy and despairing.',false),
(26,'b1266','Confidence',3,'b126','b','b1','Mental functions that produce a personal disposition that is self-assured, bold and assertive, as contrasted to being timid, insecure and self-effacing.',false),
(27,'b1267','Trustworthiness',3,'b126','b','b1','Mental functions that produce a personal disposition that is dependable and principled, as contrasted to being deceitful and antisocial.',false),
(28,'b1268','Temperament and personality functions, other specified',3,'b126','b','b1',null,true),
(29,'b1269','Temperament and personality functions, unspecified',3,'b126','b','b1',null,true),
(30,'b130','Energy and drive functions',2,'b1','b','b1','General mental functions of physiological and psychological mechanisms that cause the individual to move towards satisfying specific needs and general goals in a persistent manner.',false),
(31,'b1300','Energy level',3,'b130','b','b1','Mental functions that produce vigour and stamina.',false),
(32,'b1301','Motivation',3,'b130','b','b1','Mental functions that produce the incentive to act; the conscious or unconscious driving force for action.',false),
(33,'b1302','Appetite',3,'b130','b','b1','Mental functions that produce a natural longing or desire, especially the natural and recurring desire for food and drink.',false),
(34,'b1303','Craving',3,'b130','b','b1','Mental functions that produce the urge to consume substances, including substances that can be abused.',false),
(35,'b1304','Impulse control',3,'b130','b','b1','Mental functions that regulate and resist sudden intense urges to do something.',false),
(36,'b1308','Energy and drive functions, other specified',3,'b130','b','b1',null,true),
(37,'b1309','Energy and drive functions, unspecified',3,'b130','b','b1',null,true),
(38,'b134','Sleep functions',2,'b1','b','b1','General mental functions of periodic, reversible and selective physical and mental disengagement from one’s immediate environment accompanied by characteristic physiological changes.',false),
(39,'b1340','Amount of sleep',3,'b134','b','b1','Mental functions involved in the time spent in the state of sleep in the diurnal cycle or circadian rhythm.',false),
(40,'b1341','Onset of sleep',3,'b134','b','b1','Mental functions that produce the transition between wakefulness and sleep.',false),
(41,'b1342','Maintenance of sleep',3,'b134','b','b1','Mental functions that sustain the state of being asleep.',false),
(42,'b1343','Quality of sleep',3,'b134','b','b1','Mental functions that produce the natural sleep leading to optimal physical and mental rest and relaxation.',false),
(43,'b1344','Functions involving the sleep cycle',3,'b134','b','b1','Mental functions that produce rapid eye movement (REM) sleep (associated with dreaming) and non-rapid eye movement sleep (NREM) (characterized by the traditional concept of sleep as a time of decreased physiological and psychological activity).',false),
(44,'b1348','Sleep functions, other specified',3,'b134','b','b1',null,true),
(45,'b1349','Sleep functions, unspecified',3,'b134','b','b1',null,true),
(46,'b139','Global mental functions, other specified and unspecified',2,'b1','b','b1',null,true),
(47,'b140','Attention functions',2,'b1','b','b1','Specific mental functions of focusing on an external stimulus or internal experience for the required period of time.',false),
(48,'b1400','Sustaining attention',3,'b140','b','b1','Mental functions that produce concentration for the period of time required.',false),
(49,'b1401','Shifting attention',3,'b140','b','b1','Mental functions that permit refocusing concentration from one stimulus to another.',false),
(50,'b1402','Dividing attention',3,'b140','b','b1','Mental functions that permit focusing on two or more stimuli at the same time.',false),
(51,'b1403','Sharing attention',3,'b140','b','b1','Mental functions that permit focusing on the same stimulus by two or more people, such as a child and a caregiver both focusing on a toy.',false),
(52,'b1408','Attention functions, other specified',3,'b140','b','b1',null,true),
(53,'b1409','Attention functions, unspecified',3,'b140','b','b1',null,true),
(54,'b144','Memory functions',2,'b1','b','b1','Specific mental functions of registering and storing information and retrieving it as needed.',false),
(55,'b1440','Short-term memory',3,'b144','b','b1','Mental functions that produce a temporary, disruptable memory store of around 30 seconds duration from which information is lost if not consolidated into long-term memory.',false),
(56,'b1441','Long-term memory',3,'b144','b','b1','Mental functions that produce a memory system permitting the long-term storage of information from short-term memory and both autobiographical memory for past events and semantic memory for language and facts.',false),
(57,'b1442','Retrieval of memory',3,'b144','b','b1','Specific mental functions of recalling information stored in long-term memory and bringing it into awareness.',false),
(58,'b1448','Memory functions, other specified',3,'b144','b','b1',null,true),
(59,'b1449','Memory functions, unspecified',3,'b144','b','b1',null,true),
(60,'b147','Psychomotor functions',2,'b1','b','b1','Specific mental functions of control over both motor and psychological events at the body level.',false),
(61,'b1470','Psychomotor control',3,'b147','b','b1','Mental functions that regulate the speed of behaviour or response time that involves both motor and psychological components, such as in disruption of control producing psychomotor retardation (moving and speaking slowly; decrease in gesturing and spontaneity) or psychomotor excitement (excessive behavioural and cognitive activity, usually nonproductive and often in response to inner tension as in toe-tapping, hand-wringing, agitation, or restlessness.)',false),
(62,'b1471','Quality of psychomotor functions',3,'b147','b','b1','Mental functions that produce nonverbal behaviour in the proper sequence and character of its subcomponents, such as hand and eye coordination, or gait.',false),
(63,'b1478','Psychomotor functions, other specified',3,'b147','b','b1',null,true),
(64,'b1479','Psychomotor functions, unspecified',3,'b147','b','b1',null,true),
(65,'b152','Emotional functions',2,'b1','b','b1','Specific mental functions related to the feeling and affective components of the processes of the mind.',false),
(66,'b1520','Appropriateness of emotion',3,'b152','b','b1','Mental functions that produce congruence of feeling or affect with the situation, such as happiness at receiving good news.',false),
(67,'b1521','Regulation of emotion',3,'b152','b','b1','Mental functions that control the experience and display of affect.',false),
(68,'b1522','Range of emotion',3,'b152','b','b1','Mental functions that produce the spectrum of experience of arousal of affect or feelings such as love, hate, anxiousness, sorrow, joy, fear and anger.',false),
(69,'b1528','Emotional functions, other specified',3,'b152','b','b1',null,true),
(70,'b1529','Emotional functions, unspecified',3,'b152','b','b1',null,true),
(71,'b156','Perceptual functions',2,'b1','b','b1','Specific mental functions of recognizing and interpreting sensory stimuli.',false),
(72,'b1560','Auditory perception',3,'b156','b','b1','Mental functions involved in discriminating sounds, tones, pitches and other acoustic stimuli.',false),
(73,'b1561','Visual perception',3,'b156','b','b1','Mental functions involved in discriminating shape, size, colour and other ocular stimuli.',false),
(74,'b1562','Olfactory perception',3,'b156','b','b1','Mental functions involved in distinguishing differences in smells.',false),
(75,'b1563','Gustatory perception',3,'b156','b','b1','Mental functions involved in distinguishing differences in tastes, such as sweet, sour, salty and bitter stimuli, detected by the tongue.',false),
(76,'b1564','Tactile perception',3,'b156','b','b1','Mental functions involved in distinguishing differences in texture, such as rough or smooth stimuli, detected by touch.',false),
(77,'b1565','Visuospatial perception',3,'b156','b','b1','Mental function involved in distinguishing by sight the relative position of objects in the environment or in relation to oneself.',false),
(78,'b1568','Perceptual functions, other specified',3,'b156','b','b1',null,true),
(79,'b1569','Perceptual functions, unspecified',3,'b156','b','b1',null,true),
(80,'b160','Thought functions',2,'b1','b','b1','Specific mental functions related to the ideational component of the mind.',false),
(81,'b1600','Pace of thought',3,'b160','b','b1','Mental functions that govern speed of the thinking process.',false),
(82,'b1601','Form of thought',3,'b160','b','b1','Mental functions that organize the thinking process as to its coherence and logic.',false),
(83,'b1602','Content of thought',3,'b160','b','b1','Mental functions consisting of the ideas that are present in the thinking process and what is being conceptualized.',false),
(84,'b1603','Control of thought',3,'b160','b','b1','Mental functions that provide volitional control of thinking and are recognized as such by the person.',false),
(85,'b1608','Thought functions, other specified',3,'b160','b','b1',null,true),
(86,'b1609','Thought functions, unspecified',3,'b160','b','b1',null,true),
(87,'b164','Higher-level cognitive functions',2,'b1','b','b1','Specific mental functions especially dependent on the frontal lobes of the brain, including complex goal-directed behaviours such as decision-making, abstract thinking, planning and carrying out plans, mental flexibility, and deciding which behaviours are appropriate under what circumstances; often called executive functions.',false),
(88,'b1640','Abstraction',3,'b164','b','b1','Mental functions of creating general ideas, qualities or characteristics out of, and distinct from, concrete realities, specific objects or actual instances.',false),
(89,'b1641','Organization and planning',3,'b164','b','b1','Mental functions of coordinating parts into a whole, of systematizing; the mental function involved in developing a method of proceeding or acting.',false),
(90,'b1642','Time management',3,'b164','b','b1','Mental functions of ordering events in chronological sequence, allocating amounts of time to events and activities.',false),
(91,'b1643','Cognitive flexibility',3,'b164','b','b1','Mental functions of changing strategies, or shifting mental sets, especially as involved in problem-solving.',false),
(92,'b1644','Insight',3,'b164','b','b1','Mental functions of awareness and understanding of oneself and one''s behaviour.',false),
(93,'b1645','Judgement',3,'b164','b','b1','Mental functions involved in discriminating between and evaluating different options, such as those involved in forming an opinion.',false),
(94,'b1646','Problem-solving',3,'b164','b','b1','Mental functions of identifying, analysing and integrating incongruent or conflicting information into a solution.',false),
(95,'b1648','Higher-level cognitive functions, other specified',3,'b164','b','b1',null,true),
(96,'b1649','Higher-level cognitive functions, unspecified',3,'b164','b','b1',null,true),
(97,'b167','Mental functions of language',2,'b1','b','b1','Specific mental functions of recognizing and using signs, symbols and other components of a language.',false),
(98,'b1670','Reception of language',3,'b167','b','b1','Specific mental functions of decoding messages in spoken, written or other forms, such as sign language, to obtain their meaning.',false),
