(1124,'d845','Acquiring, keeping and terminating a job',2,'d8','d','d8','Seeking, finding and choosing employment, being hired and accepting employment, maintaining and advancing through a job, trade, occupation or profession, and leaving a job in an appropriate manner.',false),
(1125,'d8450','Seeking employment',3,'d845','d','d8','Locating and choosing a job, in a trade, profession or other form of employment, and performing the required tasks to get hired, such as showing up at the place of employment or participating in a job interview.',false),
(1126,'d8451','Maintaining a job',3,'d845','d','d8','Performing job-related tasks to keep an occupation, trade, profession or other form of employment, and obtaining promotion and other advancements in employment.',false),
(1127,'d8452','Terminating a job',3,'d845','d','d8','Leaving or quitting a job in the appropriate manner.',false),
