(1129,'d8459','Acquiring, keeping and terminating a job, unspecified',3,'d845','d','d8',null,true),
(1130,'d850','Remunerative employment',2,'d8','d','d8','Engaging in all aspects of work, as an occupation, trade, profession or other form of employment, for payment, as an employee, full or part time, or self-employed, such as seeking employment and getting a job, doing the required tasks of the job, attending work on time as required, supervising other workers or being supervised, and performing required tasks alone or in groups.',false),
(1131,'d8500','Self-employment',3,'d850','d','d8','Engaging in remunerative work sought or generated by the individual, or contracted from others without a formal employment relationship, such as migratory agricultural work, working as a free-lance writer or consultant, short-term contract work, working as an artist or crafts person, owning and running a shop or other business.',false),
(1132,'d8501','Part-time employment',3,'d850','d','d8','Engaging in all aspects of work for payment on a part-time basis, as an employee, such as seeking employment and getting a job, doing the tasks required of the job, attending work on time as required, supervising other workers or being supervised, and performing required tasks alone or in groups.',false),
(1133,'d8502','Full-time employment',3,'d850','d','d8','Engaging in all aspects of work for payment on a full-time basis, as an employee, such as seeking employment and getting a job, doing the required tasks of the job, attending work on time as required, supervising other workers or being supervised, and performing required tasks alone or in groups.',false),
(1134,'d8508','Remunerative employment, other specified',3,'d850','d','d8',null,true),
(1135,'d8509','Remunerative employment, unspecified',3,'d850','d','d8',null,true),
(1136,'d855','Non-remunerative employment',2,'d8','d','d8','Engaging in all aspects of work in which pay is not provided, full-time or part-time, including organized work activities, doing the required tasks of the job, attending work on time as required, supervising other workers or being supervised, and performing required tasks alone or in groups, such as volunteer work, charity work, working for a community or religious group without remuneration, working around the home without remuneration.',false),
