(1399,'e580','Health services, systems and policies',2,'e5','e','e5','Services, systems and policies for preventing and treating health problems, providing medical rehabilitation and promoting a healthy lifestyle.',false),
(1400,'e5800','Health services',3,'e580','e','e5','Services and programmes at a local, community, regional, state or national level, aimed at delivering interventions to individuals for their physical, psychological and social well-being, such as health promotion and disease prevention services, primary care services, acute care, rehabilitation and long-term care services; services that are publicly or privately funded, delivered on a short-term, long-term, periodic or one-time basis, in a variety of service settings such as community, home-based, school and work settings, general hospitals, speciality hospitals, clinics, and residential and non-residential care facilities, including those who provide these services.',false),
(1401,'e5801','Health systems',3,'e580','e','e5','Administrative control and monitoring mechanisms that govern the range of services provided to individuals for their physical, psychological and social well-being, in a variety of settings including community, home-based, school and work settings, general hospitals, speciality hospitals, clinics, and residential and non-residential care facilities, such as systems for implementing regulations and standards that determine eligibility for services, provision of devices, assistive technology or other adapted equipment, and legislation such as health acts that govern features of a health system such as accessibility, universality, portability, public funding and comprehensiveness.',false),
(1402,'e5802','Health policies',3,'e580','e','e5','Legislation, regulations and standards that govern the range of services provided to individuals for their physical, psychological and social well-being, in a variety of settings including community, home-based, school and work settings, general hospitals, speciality hospitals, clinics, and residential and non-residential care facilities, such as policies and standards that determine eligibility for services, provision of devices, assistive technology or other adapted equipment, and legislation such as health acts that govern features of a health system such as accessibility, universality, portability, public funding and comprehensiveness.',false),
(1403,'e5808','Health services, systems and policies, other specified',3,'e580','e','e5',null,true),
(1404,'e5809','Health services, systems and policies, unspecified',3,'e580','e','e5',null,true),
(1405,'e585','Education and training services, systems and policies',2,'e5','e','e5','Services, systems and policies for the acquisition, maintenance and improvement of knowledge, expertise and vocational or artistic skills. See UNESCO''s International Standard Classification of Education (ISCED-1997).',false),
(1406,'e5850','Education and training services',3,'e585','e','e5','Services and programmes concerned with education and the acquisition, maintenance and improvement of knowledge, expertise and vocational or artistic skills, such as those provided for different levels of education (e.g. preschool, primary school, secondary school, post-secondary institutions, professional programmes, training and skills programmes, apprenticeships and continuing education), including those who provide these services.',false),
(1407,'e5851','Education and training systems',3,'e585','e','e5','Administrative control and monitoring mechanisms that govern the delivery of education programmes, such as systems for the implementation of policies and standards that determine eligibility for public or private education and special needs-based programmes; local, regional or national boards of education or other authoritative bodies that govern features of the education systems, including curricula, size of classes, numbers of schools in a region, fees and subsidies, special meal programmes and after-school care services.',false),
(1408,'e5852','Education and training policies',3,'e585','e','e5','Legislation, regulations and standards that govern the delivery of education programme, such as policies and standards that determine eligibility for public or private education and special needs-based programmes, and dictate the structure of local, regional or national boards of education or other authoritative bodies that govern features of the education system, including curricula, size of classes, numbers of schools in a region, fees and subsidies, special meal programmes and after-school care services.',false),
(1409,'e5858','Education and training services, systems and policies, other specified',3,'e585','e','e5',null,true),
(1410,'e5859','Education and training services, systems and policies, unspecified',3,'e585','e','e5',null,true),
(1411,'e590','Labour and employment services, systems and policies',2,'e5','e','e5','Services, systems and policies related to finding suitable work for persons who are unemployed or looking for different work, or to support individuals already employed who are seeking promotion.',false),
(1412,'e5900','Labour and employment services',3,'e590','e','e5','Services and programmes provided by local, regional or national governments, or private organizations to find suitable work for persons who are unemployed or looking for different work, or to support individuals already employed, such as services of employment search and preparation, reemployment, job placement, outplacement, vocational follow-up, occupational health and safety services, and work environment services (e.g. ergonomics, human resources and personnel management services, labour relations services, professional association services), including those who provide these services.',false),
(1413,'e5901','Labour and employment systems',3,'e590','e','e5','Administrative control and monitoring mechanisms that govern the distribution of occupations and other forms of remunerative work in the economy, such as systems for implementing policies and standards for employment creation, employment security, designated and competitive employment, labour standards and law, and trade unions.',false),
(1414,'e5902','Labour and employment policies',3,'e590','e','e5','Legislation, regulations and standards that govern the distribution of occupations and other forms of remunerative work in the economy, such as standards and policies for employment creation, employment security, designated and competitive employment, labour standards and law, and trade unions.',false),
(1415,'e5908','Labour and employment services, systems and policies, other specified',3,'e590','e','e5',null,true),
(1416,'e5909','Labour and employment services, systems and policies, unspecified',3,'e590','e','e5',null,true),
(1417,'e595','Political services, systems and policies',2,'e5','e','e5','Services, systems and policies related to voting, elections and governance of countries, regions and communities, as well as international organizations.',false),
(1418,'e5950','Political services',3,'e595','e','e5','Services and structures such as local, regional and national governments, international organizations and the people who are elected or nominated to positions within these structures, such as the United Nations, European Union, governments, regional authorities, local village authorities, traditional leaders.',false),
(1419,'e5951','Political systems',3,'e595','e','e5','Structures and related operations that organise political and economic power in a society, such as executive and legislative branches of government, and the constitutional or other legal sources from which they derive their authority, such as political organizational doctrine, constitutions, agencies of executive and legislative branches of government, the military.',false),
(1420,'e5952','Political policy',3,'e595','e','e5','Laws and policies formulated and enforced through political systems that govern the operation of the political system, such as policies governing election campaigns, registration of political parties, voting, and members in international political organizations, including treaties, constitutional and other law governing legislation and regulation.',false),
(1421,'e5958','Political services, systems and policies, other specified',3,'e595','e','e5',null,true),
(1422,'e5959','Political services, systems and policies, unspecified',3,'e595','e','e5',null,true),
